// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetAuthSession Get browser access state
	// (GET /api/v1/auth/session)
	GetAuthSession(ctx context.Context, request GetAuthSessionRequestObject) (GetAuthSessionResponseObject, error)
	// ListSchedules List schedules
	// (GET /api/v1/schedules)
	ListSchedules(ctx context.Context, request ListSchedulesRequestObject) (ListSchedulesResponseObject, error)
	// CreateSchedule Create a schedule
	// (POST /api/v1/schedules)
	CreateSchedule(ctx context.Context, request CreateScheduleRequestObject) (CreateScheduleResponseObject, error)
	// PreviewSchedule Preview five future cron occurrences
	// (POST /api/v1/schedules/preview)
	PreviewSchedule(ctx context.Context, request PreviewScheduleRequestObject) (PreviewScheduleResponseObject, error)
	// GetSettings Get allowed environment names
	// (GET /api/v1/schedules/settings)
	GetSettings(ctx context.Context, request GetSettingsRequestObject) (GetSettingsResponseObject, error)
	// DeleteSchedule Soft delete a schedule
	// (DELETE /api/v1/schedules/{id})
	DeleteSchedule(ctx context.Context, request DeleteScheduleRequestObject) (DeleteScheduleResponseObject, error)
	// GetSchedule Get a schedule including deleted records
	// (GET /api/v1/schedules/{id})
	GetSchedule(ctx context.Context, request GetScheduleRequestObject) (GetScheduleResponseObject, error)
	// UpdateSchedule Update selected schedule fields
	// (PATCH /api/v1/schedules/{id})
	UpdateSchedule(ctx context.Context, request UpdateScheduleRequestObject) (UpdateScheduleResponseObject, error)
	// ListOccurrences Read stored history without calling the core
	// (GET /api/v1/schedules/{id}/occurrences)
	ListOccurrences(ctx context.Context, request ListOccurrencesRequestObject) (ListOccurrencesResponseObject, error)
	// GetOccurrence Read a stored occurrence without calling the core
	// (GET /api/v1/schedules/{id}/occurrences/{occurrence_id})
	GetOccurrence(ctx context.Context, request GetOccurrenceRequestObject) (GetOccurrenceResponseObject, error)
	// GetOccurrenceResult Explicitly fetch the current result from the Orpheus core
	// (GET /api/v1/schedules/{id}/occurrences/{occurrence_id}/result)
	GetOccurrenceResult(ctx context.Context, request GetOccurrenceResultRequestObject) (GetOccurrenceResultResponseObject, error)
	// ResetSession Detach the reusable session for the next occurrence
	// (POST /api/v1/schedules/{id}/reset-session)
	ResetSession(ctx context.Context, request ResetSessionRequestObject) (ResetSessionResponseObject, error)
	// BrowserCallback Consume a signed SAML HTTP-POST response
	// (POST /auth/callback)
	BrowserCallback(ctx context.Context, request BrowserCallbackRequestObject) (BrowserCallbackResponseObject, error)
	// BrowserLogin Start SP-initiated SAML login
	// (GET /auth/login)
	BrowserLogin(ctx context.Context, request BrowserLoginRequestObject) (BrowserLoginResponseObject, error)
	// BrowserLogout Revoke the local browser session
	// (POST /auth/logout)
	BrowserLogout(ctx context.Context, request BrowserLogoutRequestObject) (BrowserLogoutResponseObject, error)
	// SamlMetadata Read service provider metadata
	// (GET /saml/metadata)
	SamlMetadata(ctx context.Context, request SamlMetadataRequestObject) (SamlMetadataResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

